public abstract class ConfigChangeEvent : System.IEquatable<Dalamud.Game.Config.ConfigChangeEvent>
{
    public ConfigChangeEvent(System.Enum option) { }
    public ConfigChangeEvent(System.Enum option, string name) { }
    public void Deconstruct(ref System.Enum option) { }
    public System.Enum Option => default!;
    public string Name => null!;
}

public class ConfigChangeEvent<T> : Dalamud.Game.Config.ConfigChangeEvent, System.IEquatable<Dalamud.Game.Config.ConfigChangeEvent> where T : System.Enum
{
    public ConfigChangeEvent(T option) { }
    public ConfigChangeEvent(T option, string name) { }
    public void Deconstruct(ref T configOption) { }
    public T ConfigOption { get => default!; set { } }
    public bool Equals(Dalamud.Game.Config.ConfigChangeEvent other) { return default!; }
}

public class ConfigOptionNotFoundException : System.Exception, System.Runtime.Serialization.ISerializable
{
    public ConfigOptionNotFoundException(string sectionName, string configOptionName) { }
}

public class FloatConfigProperties : System.IEquatable<Dalamud.Game.Config.FloatConfigProperties>
{
    public FloatConfigProperties(float Default, float Minimum, float Maximum) { }
    public float Default { get => default!; set { } }
    public float Minimum { get => default!; set { } }
    public float Maximum { get => default!; set { } }
    public bool Equals(Dalamud.Game.Config.FloatConfigProperties other) { return default!; }
}

public class GameConfigOptionAttribute : System.Attribute
{
    public GameConfigOptionAttribute(string name, Dalamud.Game.Config.ConfigType type, bool settable = true) { }
    public string Name => null!;
    public Dalamud.Game.Config.ConfigType Type => default!;
    public bool Settable => default!;
}

public class GameConfigSection
{
    public bool TryGetBool(string name, ref bool value) { return default!; }
    public bool TryGet(string name, ref bool value) { return default!; }
    public bool GetBool(string name) { return default!; }
    public void Set(string name, bool value) { }
    public bool TryGetUInt(string name, ref uint value) { return default!; }
    public bool TryGet(string name, ref uint value) { return default!; }
    public uint GetUInt(string name) { return default!; }
    public void Set(string name, uint value) { }
    public bool TryGetFloat(string name, ref float value) { return default!; }
    public bool TryGet(string name, ref float value) { return default!; }
    public float GetFloat(string name) { return default!; }
    public void Set(string name, float value) { }
    public bool TryGetString(string name, ref string value) { return default!; }
    public bool TryGet(string name, ref string value) { return default!; }
    public string GetString(string name) { return null!; }
    public bool TryGetStringAsEnum<T>(string name, ref T value) where T : struct, System.Enum { return default!; }
    public void Set(string name, string value) { }
    public bool TryGetProperties(string name, ref Dalamud.Game.Config.UIntConfigProperties properties) { return default!; }
    public bool TryGetProperties(string name, ref Dalamud.Game.Config.FloatConfigProperties properties) { return default!; }
    public bool TryGetProperties(string name, ref Dalamud.Game.Config.StringConfigProperties properties) { return default!; }
    public uint ConfigCount => default!;
    public string SectionName => null!;
}

